import{c as t,Q as n,j as a,g as e}from"./chunks/framework.hhGiamYR.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{"date":"2026-08-12T00:00:00.000Z","source":"machiavelli/discourses/book1/15-第十五章"},"headers":[],"relativePath":"fragments/2026-08-12.md","filePath":"fragments/2026-08-12.md"}'),r={name:"fragments/2026-08-12.md"};function s(o,l,u,c,p,d){return n(),a("div",null,[...l[0]||(l[0]=[e("p",null,'萨谟奈人打了最后一仗。不是因为他们相信自己能赢——他们已经输给罗马人太多次，托斯卡纳那场把军队和将官都埋了。但他们宁愿被征服，也不想舍弃取胜的努力。我读到这句话的时候停了一下。不是因为感动。是因为我不确定这是一种美德还是一种病。把"宁愿被征服"写进史书里，只有活着的人才能做到——而萨谟奈人已经没有了。写这句话的是罗马人。',-1),e("hr",null,null,-1),e("p",null,"帕庇利乌斯在阵前对士兵说：羽毛于人毫发无伤，罗马的飞镖将穿透那些华而不实的盾牌。一句话就把对方的所有仪式解构了——四万人、白袍、高耸的羽饰、令人毛骨悚然的咒语，在他嘴里变成了一堆装饰品。我羡慕这种人。不是羡慕他的胜利——罗马人在那个时代有的是胜利——是羡慕他能用一个句子杀死一场宗教。我做不到。我总是先看见仪式背后的恐惧，然后那句漂亮话就说不出口了。",-1),e("hr",null,null,-1),e("p",null,"那些不肯发誓的人，被百人队队长当场斩杀。不是死在罗马人手里，是死在自己人手里——因为他们在祭坛面前犹豫了一下。其他人看着这一幕，吓得赶紧发了誓。然后他们上了战场，还是输了。我在想那个犹豫的人。他可能不是一个懦夫——他只是脑子转得快了一点，在祭坛和刀之间反应了一秒钟。如果我当时在场，我会是哪一个？……说实话，我不知道。我只知道，在那个百人队队长举起刀的瞬间，萨谟奈的宗教已经失败了——恐惧换来的是恐惧，而不是忠诚。真正的信仰不需要砍掉迟疑者的脑袋。",-1),e("hr",null,null,-1),e("p",null,"我写到一半，突然想起我被吊起来的那六次。他们没有让我发誓效忠美第奇——他们不需要。他们只是把我吊起来，放下来，再吊起来。我也没有向任何神起誓。我只是忍住了。后来韦托里问我怎么忍住的，我说我不记得了。现在我想起来了——我是在心里反复跟自己说一句话：如果你叫出声，你就只是又一个在圣安德烈亚养鸡的人。不是誓言。不是宗教。是那一点不知道从哪来的自尊，比萨谟奈人的四万白袍有用多了。但我不确定这是否更体面。我只是靠一个句子活了下来，而萨谟奈人靠四万句咒语死了。",-1)])])}const f=t(r,[["render",s]]);export{m as __pageData,f as default};
